import{_ as t,o as s,c as i,a4 as r}from"./chunks/framework.BE47AOxC.js";const b=JSON.parse('{"title":"ADR-0067 — Le site du projet est hébergé dans le dépôt de distribution, en une seule version","description":"Extrait de docs/adr/0067-site-du-projet-heberge-dans-le-depot-de-distribution.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0067 — Le site du projet est hébergé dans le dépôt de distribution, en une seule version","description":"Extrait de docs/adr/0067-site-du-projet-heberge-dans-le-depot-de-distribution.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0067-site-du-projet-heberge-dans-le-depot-de-distribution.md","filePath":"developpeurs/adr/0067-site-du-projet-heberge-dans-le-depot-de-distribution.md"}'),o={name:"developpeurs/adr/0067-site-du-projet-heberge-dans-le-depot-de-distribution.md"};function d(n,e,a,u,l,c){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0067--le-site-du-projet-est-hébergé-dans-le-dépôt-de-distribution-en-une-seule-version" tabindex="-1">ADR-0067 — Le site du projet est hébergé dans le dépôt de distribution, en une seule version <a class="header-anchor" href="#adr-0067--le-site-du-projet-est-hébergé-dans-le-dépôt-de-distribution-en-une-seule-version" aria-label="Permalink to &quot;ADR-0067 — Le site du projet est hébergé dans le dépôt de distribution, en une seule version {#adr-0067--le-site-du-projet-est-hébergé-dans-le-dépôt-de-distribution-en-une-seule-version}&quot;">​</a></h1><p><strong>Date :</strong> 7 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> lot 13 (issue #7), réalisation de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0048-site-du-projet-genere-depuis-le-depot">ADR-0048</a> : le dépôt du code est privé, et le Product Owner ne veut pas encore de documentation par version <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0048-site-du-projet-genere-depuis-le-depot">ADR-0048</a>, décisions n°1 (« la documentation de chaque version reste consultable ») et n°3 (publication sur GitHub Pages « à l&#39;adresse fournie par GitHub ») ; même mécanisme que l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0063-depot-public-de-distribution">ADR-0063</a></p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0048 décide un site statique, généré depuis le dépôt avec VitePress, publié sur GitHub Pages, et dont la documentation de chaque version reste consultable. Sa réalisation (lot 13) rencontre deux faits que l&#39;ADR ne pouvait pas connaître.</p><p><strong>Le dépôt du code est privé</strong> (ADR-0063), et GitHub Pages n&#39;est gratuit que pour un dépôt public. Publier le site depuis <code>Bastien-OC20/calamars</code> demanderait un abonnement payant ou de rendre le code public, ce que le Product Owner a écarté. Le dépôt public de distribution, <code>Bastien-OC20/teuthis-cms-distribution</code>, existe déjà : il porte les releases que l&#39;exploitant télécharge, et le jeton <code>JETON_DISTRIBUTION</code> (<code>Contents: Read and write</code> sur ce seul dépôt) permet déjà au workflow de publication d&#39;y écrire.</p><p><strong>Il n&#39;y a pas encore d&#39;utilisateur sur plusieurs versions.</strong> Conserver une documentation par version (sous-dossiers, sélecteur de version, recherche par version) coûterait de la construction et de la maintenance avant d&#39;avoir un seul lecteur qui en ait besoin.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Le site est publié sur la branche <code>gh-pages</code> du dépôt public de distribution.</strong> Son adresse est <code>https://bastien-oc20.github.io/teuthis-cms-distribution/</code> : la base de VitePress est donc <code>/teuthis-cms-distribution/</code>, surchargeable par la variable d&#39;environnement <code>SITE_BASE</code> le jour où un domaine propre est branché (<code>SITE_BASE=/</code>), sans rien changer d&#39;autre.</p><ul><li>Le job <code>site</code> de <code>publication-images.yml</code> construit le site à l&#39;étiquette publiée, après la publication de l&#39;installateur et des notes de la release, et pousse le résultat avec le secret <code>JETON_DISTRIBUTION</code>, comme l&#39;étape de l&#39;ADR-0063.</li><li>La branche <code>gh-pages</code> est <strong>orpheline et réduite à un seul commit</strong>, écrasé à chaque publication (poussée forcée) : l&#39;historique d&#39;un site généré n&#39;a aucun intérêt, il se reconstruit depuis l&#39;étiquette. Le dossier porte un fichier <code>.nojekyll</code>.</li><li><strong>Activer GitHub Pages sur le dépôt de distribution est un geste du Product Owner</strong> (Settings › Pages › branche <code>gh-pages</code>, racine). Le workflow met la branche à jour, il ne touche à aucun réglage du dépôt.</li></ul><p><strong>2. Une seule documentation : celle de la dernière version.</strong> Le site est reconstruit à chaque étiquette de version et remplace le précédent. Il n&#39;y a ni sous-dossier par version ni sélecteur de version. L&#39;historique de ce qui change reste dans les <strong>notes de release</strong>, que la rubrique Versions du site liste et affiche (lues dans le fichier des releases du dépôt du code à la publication, ou à défaut dans l&#39;API publique des releases du dépôt de distribution ; une construction n&#39;échoue jamais parce que le réseau manque).</p><p><strong>3. Périmètre du lot 13.</strong> Les rubriques Accueil, Installer, Documentation, Développeurs et Versions sont livrées ; <strong>la rubrique Extensions ne l&#39;est pas</strong> (elle viendra avec le catalogue généré des manifestes et des profils, sans page vide en attendant), ni le SDK.</p><p><strong>4. Tout ce qui décrit le code est généré à la construction, jamais recopié.</strong> Les sources restent dans le dépôt ; le site les lit.</p><table tabindex="0"><thead><tr><th>Page du site</th><th>Source lue à la construction</th></tr></thead><tbody><tr><td>Profils de l&#39;accueil, sélecteur de la page Installer</td><td><code>apps/api/app/bundled_plugins/profiles/*.yaml</code>, <code>deploy/installer.sh</code> (adresse de l&#39;installateur)</td></tr><tr><td>Notice d&#39;utilisation (une page par <code>##</code>)</td><td><code>docs/notice-utilisateur.md</code></td></tr><tr><td>Guide pas à pas, guide du référent</td><td><code>deploy/LISEZMOI.md</code></td></tr><tr><td>Options de l&#39;installateur</td><td><code>deploy/installer.sh</code> (le texte de <code>--aide</code>)</td></tr><tr><td>Référence de l&#39;API (une page par étiquette, et les schémas)</td><td>l&#39;OpenAPI de FastAPI, exportée par <code>site/scripts/exporter_openapi.py</code> sans base ni réseau</td></tr><tr><td>ADR</td><td><code>docs/adr/</code></td></tr><tr><td>Contribuer</td><td><code>CONTRIBUTING.md</code></td></tr><tr><td>Versions et notes</td><td>fichier ou API des releases ; constantes de <code>deploy/installer.sh</code> et de <code>publication-images.yml</code> pour la vérification des signatures</td></tr></tbody></table><p><strong>5. L&#39;installateur n&#39;est pas servi par le site.</strong> La commande affichée télécharge <code>installer.sh</code> et sa somme depuis <code>releases/latest/download</code> du dépôt de distribution (ADR-0063). L&#39;ADR-0048 prévoyait que le site les serve aussi : ce n&#39;est pas retenu, le site ne duplique pas un fichier dont la somme se vérifie à un seul endroit.</p><p><strong>6. Accessibilité et confidentialité.</strong> Le site n&#39;embarque aucun traceur, aucune police ni aucun script tiers, et sa recherche est celle de VitePress, dans le navigateur. Le job <code>site</code> de la CI passe axe (WCAG 2.1 A et AA) sur des pages de chaque rubrique aux trois largeurs, et contrôle les liens et les ancres internes. <strong>Ce contrôle ne vaut pas conformité</strong> : aucun audit manuel n&#39;est fait, et le site ne déclare aucune conformité au RGAA.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td>Publier depuis le dépôt du code</td><td>GitHub Pages n&#39;est gratuit que sur un dépôt public, et le dépôt du code reste privé (ADR-0063).</td></tr><tr><td>Déploiement par <code>actions/deploy-pages</code></td><td>Il publie sur les Pages du dépôt qui exécute le workflow, donc celui du code : même impasse.</td></tr><tr><td>Un dépôt dédié au site</td><td>Un dépôt public de plus, avec son propre jeton, alors que le dépôt de distribution existe déjà et que son jeton est déjà posé.</td></tr><tr><td>Un hébergeur tiers (Netlify, Cloudflare Pages…)</td><td>Un compte et un service de plus à gouverner, pour un site statique que GitHub Pages sert.</td></tr><tr><td>Documentation versionnée (un sous-dossier par version)</td><td>Décision du Product Owner : pas encore d&#39;utilisateurs sur plusieurs versions, et les notes de release gardent l&#39;historique. À reconsidérer le jour où deux versions sont déployées en même temps.</td></tr><tr><td>Historique conservé sur <code>gh-pages</code></td><td>Il grossirait le dépôt de distribution sans servir : chaque état du site se reconstruit depuis son étiquette.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le site est publié sans rendre le code public ni payer d&#39;hébergement, avec un secret que le Product Owner gère déjà.</li><li>Le site ne peut pas dériver du dépôt : sa documentation, son sélecteur, sa référence d&#39;API et sa liste de profils sont lus à chaque construction.</li><li>Passer au domaine propre ne demande que <code>SITE_BASE=/</code> et le réglage Pages.</li></ul><p><strong>Négatives</strong></p><ul><li>Tant qu&#39;il n&#39;y a pas de domaine propre, l&#39;adresse du site porte le nom du dépôt de distribution, et elle change une fois au branchement du domaine.</li><li>Un exploitant resté sur une ancienne version lit la documentation de la dernière : seules les notes de release disent ce qui diffère.</li><li>Le jeton <code>JETON_DISTRIBUTION</code> expire : sans renouvellement, la publication du site s&#39;arrête avec celle de l&#39;installateur.</li><li>Deux étiquettes publiées à la suite poussent l&#39;une après l&#39;autre (le job est sérialisé) : la dernière publiée l&#39;emporte.</li><li>Le site dépend de la lisibilité des sources : une section de <code>deploy/LISEZMOI.md</code> ou de la notice qui change de forme fait échouer la construction avec un message, plutôt que de laisser une page disparaître.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Site VitePress dans <code>site/</code> : Accueil, Installer (sélecteur de profil, lisible sans JavaScript), Documentation (notice découpée, guide du référent), Développeurs (référence de l&#39;API, ADR, contribution), Versions ; tout ce qui décrit le code est généré ; job <code>site</code> de <code>ci.yml</code> (export de l&#39;OpenAPI, <code>npm ci</code>, construction, axe, liens et ancres) et <code>site</code> dans <code>scripts/verifier-comme-la-ci.sh</code>. <strong>Fait le 07/10/2026</strong> (lot 13, issue #7) — construction complète, axe sans violation grave sur 34 pages des cinq rubriques aux trois largeurs, 0 lien ni ancre cassé, <code>npm audit --omit=dev</code> à 0.</li><li>[x] Première publication réelle : <strong>faite le 08/10/2026</strong> avec la v0.5.0. Le job <code>site</code> de <code>publication-images.yml</code> a poussé <code>gh-pages</code> (relancé une fois : un miroir apt muet bloquait l&#39;installation de Playwright, étape désormais bornée à 15 min, commit <code>0675564</code>). GitHub Pages servi depuis <code>gh-pages</code> à <a href="https://bastien-oc20.github.io/teuthis-cms-distribution/" target="_blank" rel="noreferrer">https://bastien-oc20.github.io/teuthis-cms-distribution/</a> : accueil, Installer, Documentation, Développeurs, Versions (v0.1.0 à v0.5.0) et Accessibilité en 200, page inconnue en 404, commande d&#39;installation <code>releases/latest/download/installer.sh</code> en 200. L&#39;activation de GitHub Pages et la rubrique Extensions restent les actions ouvertes de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0048-site-du-projet-genere-depuis-le-depot">ADR-0048</a> (cases 2 et 3) : on ne les recompte pas ici.</li><li>[ ] Rédiger la section « dépannage » du guide du référent : <code>deploy/LISEZMOI.md</code> n&#39;en a pas (le guide couvre la sauvegarde, la restauration et la mise à jour manuelle, pas le diagnostic d&#39;une pile en échec).</li><li>[ ] Audit manuel d&#39;accessibilité du site, puis déclaration d&#39;accessibilité et moyen de signaler un défaut (le contrôle axe ne vaut pas conformité).</li></ul>',24)])])}const g=t(o,[["render",d]]);export{b as __pageData,g as default};
